class Solution {
    public int maxArea(int[] height) {
        int lo = 0, hi = height.length - 1, best = 0;
        while (lo < hi) {
            int area = Math.min(height[lo], height[hi]) * (hi - lo);
            best = Math.max(best, area);
            if (height[lo] < height[hi]) lo++;
            else hi--;
        }
        return best;
    }
}

